Splat & Keyword Arguments:
# Splat — captures extra positional args
def greet(greeting, *names)
  names.each { |name| puts "#{greeting}, #{name}!" }
end
greet("Hello", "Alice", "Bob", "Charlie")

# Double splat — captures keyword args
def configure(**options)
  options.each { |k, v| puts "#{k}=#{v}" }
end
configure(host: "localhost", port: 8080, debug: true)

# Keyword arguments
def create_user(name:, age:, role: "user")
  puts "#{name} (#{age}), role: #{role}"
end
create_user(name: "Alice", age: 30)
create_user(name: "Bob", age: 25, role: "admin")

# Mixed
def complex(a, b = 2, *rest, key:, **opts, &block)
  block.call(a + b)
end

attr_accessor/reader/writer Deep Dive:
class Person
  attr_reader :name        # getter only: def name; @name; end
  attr_writer :age         # setter only: def age=(v); @age=v; end
  attr_accessor :email     # both getter and setter
  attr_reader :hobbies, :skills  # multiple at once

  def initialize(name, age, email)
    @name = name
    @age = age
    @email = email
  end

  # Custom getter (adds behavior)
  def age
    @age || 0
  end

  # Custom setter (adds validation)
  def email=(value)
    raise "Invalid email" unless value.include?("@")
    @email = value
  end
end

Hashes Deep:
# Default proc — dynamic default
h = Hash.new { |hash, key| hash[key] = key.to_s.upcase }
h[:foo]  # "FOO" (assigned automatically)
puts h   # {:foo=>"FOO"}

# Fetch with block
data = { a: 1, b: 2 }
data.fetch(:a)                # 1
data.fetch(:missing) { |k| "#{k} not found" }  # "missing not found"

# Transform
h = { a: 1, b: 2 }
h.transform_keys(&:upcase)    # {:A=>1, :B=>2}
h.transform_values { |v| v * 2 }  # {:a=>2, :b=>4}

# Dig — safe nested access
user = { profile: { address: { city: "NYC" } } }
user.dig(:profile, :address, :city)  # "NYC"
user.dig(:profile, :phone)           # nil (no error)

# Merge with block
{a: 1, b: 2}.merge({b: 3, c: 4}) { |key, old, new| old + new }
# {:a=>1, :b=>5, :c=>4}
